    /** Part instance id (from the game's SrbSnapshot). */
    readonly partInstanceId: number;
    /** Substance (from the game's SrbSnapshot). */
    readonly substance: string;
    /** Grain (from the game's SrbSnapshot). */
    readonly grain: string;
    /** Grain shape (from the game's SrbSnapshot). */
    readonly grainShape: string;
    /** Stack valid (from the game's SrbSnapshot). */
