    /** Propellant available (from the game's SrbSnapshot). */
    readonly propellantAvailable: boolean;
    /** Mass unburnable, in kilograms (from the game's SrbSnapshot). */
    readonly massUnburnableKg: number;
    /** Mass burnable, in kilograms (from the game's SrbSnapshot). */
    readonly massBurnableKg: number;
    /** Fraction (from the game's SrbSnapshot). */
    readonly fraction: number;
    /** Mass flow, in kg/s (from the game's SrbSnapshot). */
    readonly massFlowKgS: number;
    /** Burn time remaining, in seconds (from the game's SrbSnapshot). */
