  /** How fast a vessel moves. */
  interface Velocity {
    /** Orbital speed, in m/s. */
    readonly orbital: number;
    /** Speed relative to the rotating surface, in m/s. */
    readonly surface: number;
    /** Inertial speed, in m/s. */
    readonly inertial: number;
    /** Velocity vector in the parent body's CCI frame, in m/s. */
    readonly cci: Vec3;
  }

  /** A vessel's orientation and rotation rate. */
  interface Attitude {
    /** Body-to-CCI rotation. */
    readonly quat: Quat;
    /** Angular rates about the body axes, in rad/s. */
    readonly rates: Vec3;
  }

  /** A vessel's altitude, in metres. */
  interface Altitude {
    /** Altitude above the reference surface used for pressure. */
    readonly barometric: number;
    /** Height above the terrain below. */
    readonly radar: number;
  }

  /** A vessel's mass properties. */
  interface Mass {
    /** Total mass, in kilograms. */
    readonly total: number;
    /** Mass without propellant, in kilograms. */
    readonly dry: number;
    /** Propellant mass, in kilograms. */
    readonly propellant: number;
    /** Centre of mass in the vessel frame, in metres. */
    readonly centerOfMass: Vec3;
  }

